package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import jakarta.servlet.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
@RestController @ConditionalOnProperty(prefix="medical.agent-authoring",name="enabled",havingValue="true")
public final class FormalCapabilityCancellationController {
 private final ApplicationSessionIdentity identities;private final FormalCapabilityCancellation service;private final PermissionSchema json;
 public FormalCapabilityCancellationController(ApplicationSessionIdentity identities,FormalCapabilityCancellation service,PermissionSchema json){this.identities=identities;this.service=service;this.json=json;}
 @PostMapping(value="/api/agent-authoring/capability-cancellations",consumes="application/json")
 public JsonNode cancel(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String c=headers(request);var actor=identities.requireCurrent(request,auth);if(request.getContentLengthLong()>2097152)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);byte[] body=request.getInputStream().readNBytes(2097153);if(body.length>2097152)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);return envelope(service.cancel(actor,c,SimulationInputArtifactController.one(request,"Idempotency-Key"),body),response);}
 @GetMapping("/api/agent-authoring/capability-cancellation-operations") public JsonNode recover(HttpServletRequest request,HttpServletResponse response,Authentication auth){String c=headers(request);if(request.getContentLengthLong()>0||request.getHeader("Transfer-Encoding")!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);return envelope(service.recover(identities.requireCurrent(request,auth),c,SimulationInputArtifactController.one(request,"Idempotency-Key")),response);}
 private static String headers(HttpServletRequest request){if(request.getQueryString()!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);if(!"1.0.0".equals(SimulationInputArtifactController.one(request,"X-Schema-Version")))throw new SchemaRejection(ErrorCode.SCHEMA_UNSUPPORTED);String c=SimulationInputArtifactController.one(request,"X-Context-Revision");PermissionSchema.revision(c);return c;}
 private JsonNode envelope(JsonNode data,HttpServletResponse response){String id=java.util.UUID.randomUUID().toString();response.setHeader("Cache-Control","no-store");response.setHeader("X-Schema-Version","1.0.0");response.setHeader("X-Resource-Revision","1");response.setHeader("X-Request-Id",id);var r=json.object().put("schema_version","1.0.0").put("request_id",id).put("resource_revision","1");r.set("data",data);return r;}
 @ExceptionHandler(SchemaRejection.class) void invalid(SchemaRejection failure,HttpServletResponse response)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(response,422,failure.code());}
 @ExceptionHandler(TenantAccessException.class) void denied(TenantAccessException failure,HttpServletResponse response)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(response,SimulationRuleVersionController.errorStatus(failure.code()),failure.code());}
}
